result.forEach(b=>{
	//java.logType(b)
	//java.log(b)
	name=java.getString("a .title@textNodes",b)

	bookname=name.match(/《[^》]+》/)
	look=java.getString("u.0@text",b)
	time=java.getString("span.-1@text",b)
	up=java.getString("u.1@text",b)
	intro=java.getString(".intro@text",b)
	wordcount=java.getString("a span@text##字",b)
	if(bookname){
		bookname=String(bookname).replace(/《|》/g,"")
		if (booknameList.indexOf(bookname)==-1){
			booknameList.push(bookname)
			book={
				bookname:bookname,
				look:look,
				time:time,
				up:up,
				intro:intro,
				wordcount:wordcount,
				sum:1}
			bookList.push(book)
			//java.log(JSON.stringify(book))
			}else{
				bookList[booknameList.indexOf(bookname)].sum+=1
				bookList[booknameList.indexOf(bookname)].up+=up
				bookList[booknameList.indexOf(bookname)].look+=look
				bookList[booknameList.indexOf(bookname)].wordcount+=wordcount
				}
		}else{
			book={
				bookname:name,
				look:look,
				time:time,
				up:up,
				intro:intro,
				wordcount:wordcount,
				sum:1}
			bookList.push(book)
			booknameList.push(name)
			}	
	})
	result=(JSON.stringify(bookList))
