}

function sendCF() {
    let checkCodeUrl = $$$['url'] + '/checkLimitCode';
    let myCookie = java.getCookie($$$['url']);
    let ua = java.getWebViewUA();
    let header = {
	"Content-Type": "application/x-www-form-urlencoded", 
	"Accept": "application/json, text/plain, */*",
	"User-Agent": ua,
	"cookie": myCookie
   };
    code = java.getVerificationCode($$$['url'] + '/captcha');
    let data = 'checkCode=' + code;
    resp = JSON.parse(java.post(checkCodeUrl, data, header).body());
    java.longToast(resp);
    if(resp.result == "success"){
        java.longToast('\n验证成功，请返回刷新正文!');
    }else{
        java.longToast(`\n验证失败：${resp.msg}`);
    }
}

